import type {Suggestion} from '../filter-input'
import {BaseFilterElement} from '../filter-input'
import {controller, target} from '@github/catalyst'

@controller('dependabot-alerts-filter')
class DependabotAlertsFilterElement extends BaseFilterElement {
  @target declare filterKeywordWarningContainer: HTMLElement
  @target declare filterKeywordWarningMessage: HTMLElement

  override showAllQualifiersIfNoneMatch = false
  override fuzzyMatchQualifiers = true
  override showSubmissionOptionIfInvalidSearchTerms = true
  override suggestionsTitle = 'Narrow your search'

  // No space between the value and description because they are
  // a qualifier:value pair, and qualifiers and values don't have
  // a space between them.
  override spaceBetweenValueAndDescription = false

  override async fetchMatchingSuggestions(qualifier: string, filterString: string): Promise<Suggestion[]> {
    switch (this.removeNegationFromQualifierIfSupported(qualifier)) {
      case 'assignee':
        return this.fetchMatchingAssigneeSuggestions(qualifier, filterString)
      default:
        return super.fetchMatchingSuggestions(qualifier, filterString)
    }
  }

  async fetchMatchingAssigneeSuggestions(qualifier: string, filterString: string): Promise<Suggestion[]> {
    const normalizedQualifier = this.removeNegationFromQualifierIfSupported(qualifier)
    const suggestionPathAttribute = `data-suggestable-${normalizedQualifier}-path`
    const baseUrl = this.searchInput.getAttribute(suggestionPathAttribute)
    if (!baseUrl) {
      return []
    }
    const lastSearchTerm = filterString.split(',').pop() || ''

    const url = new URL(baseUrl, window.location.origin)
    url.searchParams.append('q', lastSearchTerm)

    const userSuggestions = await this.cachedJSON<{users: Array<{login: string; name: string}>}>(url.toString())
    return userSuggestions.users.map(user => ({
      value: `${qualifier}:${user.login}`,
      description: user.name,
    }))
  }
}
